  describe("Withering Fire (Factions in Action Vol. 2, Infantry Focus, p.68)", () => {
    const WITHERING_FIRE_ID = "Compendium.essence20.intercontinental_adventures.Item.7NYq9SpPjODuHF8R";
    const rangedWeaponEffect = {
      type: 'weaponEffect',
      flags: {},
      system: { classification: { skill: 'targeting' }, damageType: 'ballistic', damageValue: 1 },
    };

    function makeAttackerActor({ disposition = 1, hasPerk = true } = {}) {
      const items = hasPerk ? [{ type: 'perk', flags: { core: { sourceId: WITHERING_FIRE_ID } } }] : [];
      items.get = jest.fn(() => null);

      return {
        ...mockActor,
        id: 'roller1',
        items,
        getActiveTokens: jest.fn(() => [{ document: { disposition } }]),
        getRollData: jest.fn(() => ({ skills: { targeting: { modifier: '0', shift: 'd20' } } })),
      };
    }

    function makeTargetActor({ flag = null } = {}) {
      return {
        uuid: 'Actor.target1',
        system: { size: 'common' },
        statuses: new Set(),
        getFlag: jest.fn((scope, key) => (key == 'attackedByAllyThisRound' ? flag : undefined)),
      };
    }

    const alreadyAttackedFlag = { combatId: 'combat1', round: 2, disposition: 1, attackerId: 'ally1' };
    let originalGameUsers, originalGameSettings, originalGameSocket, originalGameActors;

    beforeEach(() => {
      game.combat = { id: 'combat1', round: 2 };
      originalGameUsers = global.game.users;
      originalGameSettings = global.game.settings;
      originalGameSocket = global.game.socket;
      originalGameActors = global.game.actors;
      global.game.users = [{ isGM: true, active: true }];
      global.game.settings = { get: jest.fn(() => 1) };
      global.game.socket = { emit: jest.fn() };
      global.game.actors = { party: legacyPoolParty() };
    });

    afterEach(() => {
      game.combat = null;
      global.game.users = originalGameUsers;
      global.game.settings = originalGameSettings;
      global.game.socket = originalGameSocket;
      global.game.actors = originalGameActors;
    });

    test("witheringFireAvailable is true against a target already attacked by an ally this round, with a Story Point and a GM connected", async () => {
      const target = makeTargetActor({ flag: alreadyAttackedFlag });
      game.user.targets.first.mockReturnValue({ actor: target });
      const rollDialog = createMockRollDialog();
      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
      });
      dice._rollSkillHelper = jest.fn();

      await dice.rollSkill({ ...dataset, skill: 'targeting' }, makeAttackerActor(), rangedWeaponEffect);

      expect(rollDialog.getSkillRollOptions.mock.calls[0][0].witheringFireAvailable).toBe(true);
    });

    test("witheringFireAvailable is false without the Perk, without a prior ally attack, or without a Story Point/GM", async () => {
      const rollDialog = createMockRollDialog();
      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
      });
      dice._rollSkillHelper = jest.fn();

      game.user.targets.first.mockReturnValue({ actor: makeTargetActor({ flag: alreadyAttackedFlag }) });
      await dice.rollSkill({ ...dataset, skill: 'targeting' }, makeAttackerActor({ hasPerk: false }), rangedWeaponEffect);
      expect(rollDialog.getSkillRollOptions.mock.calls[0][0].witheringFireAvailable).toBe(false);

      game.user.targets.first.mockReturnValue({ actor: makeTargetActor({ flag: null }) });
      await dice.rollSkill({ ...dataset, skill: 'targeting' }, makeAttackerActor(), rangedWeaponEffect);
      expect(rollDialog.getSkillRollOptions.mock.calls[1][0].witheringFireAvailable).toBe(false);

      global.game.settings = { get: jest.fn(() => 0) };
      game.user.targets.first.mockReturnValue({ actor: makeTargetActor({ flag: alreadyAttackedFlag }) });
      await dice.rollSkill({ ...dataset, skill: 'targeting' }, makeAttackerActor(), rangedWeaponEffect);
      expect(rollDialog.getSkillRollOptions.mock.calls[2][0].witheringFireAvailable).toBe(false);
    });

    test("spends 1 Story Point and flags checkContext.isWitheringFireAttempt when checked", async () => {
      const target = makeTargetActor({ flag: alreadyAttackedFlag });
      game.user.targets.first.mockReturnValue({ actor: target });
      const rollDialog = createMockRollDialog();
      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        dif: '10', applyWitheringFire: true,
      });
      dice._rollSkillHelper = jest.fn();
      const actor = makeAttackerActor();

      await dice.rollSkill({ ...dataset, skill: 'targeting', dif: '10' }, actor, rangedWeaponEffect);

      expect(game.socket.emit).toHaveBeenCalledWith('system.essence20', {
        action: 'spendStoryPoints', amount: 1, actorName: undefined,
      });
      const checkContext = dice._rollSkillHelper.mock.calls[0][4];
      expect(checkContext.isWitheringFireAttempt).toBe(true);
    });

    test("doesn't spend a Story Point when the checkbox isn't checked", async () => {
      const target = makeTargetActor({ flag: alreadyAttackedFlag });
      game.user.targets.first.mockReturnValue({ actor: target });
      const rollDialog = createMockRollDialog();
      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1, dif: '10',
      });
      dice._rollSkillHelper = jest.fn();

      await dice.rollSkill({ ...dataset, skill: 'targeting', dif: '10' }, makeAttackerActor(), rangedWeaponEffect);

      expect(game.socket.emit).not.toHaveBeenCalled();
      const checkContext = dice._rollSkillHelper.mock.calls[0][4];
      expect(checkContext.isWitheringFireAttempt).toBe(false);
    });
  });

