    describe("Straight Shooter (Transformers CRB, Gunner base, Gunslinger Focus, 3rd level, p.70)", () => {
      const STRAIGHT_SHOOTER_TF_ID = "Compendium.essence20.tf_crb.Item.I4Sy2sJIudLAeUlN";
      const ballisticWeaponEffect = {
        type: 'weaponEffect',
        flags: { essence20: { parentId: 'weapon1' } },
        system: { classification: { skill: 'targeting', style: 'ranged' } },
      };
      const noShiftDownModifiers = {
        shiftUp: 0, shiftDown: 0, edge: false, snag: false, sources: [], pendingBonusesToClear: [],
      };
      const hasShiftDownModifiers = {
        shiftUp: 0, shiftDown: 2, edge: false, snag: false, sources: [], pendingBonusesToClear: [],
      };

      function makeGunslingerActor({ perkIds = [], hasWeapon = true } = {}) {
        const items = perkIds.map(id => ({ type: 'perk', flags: { core: { sourceId: id } } }));
        items.get = jest.fn(id => (id == 'weapon1' && hasWeapon
          ? { flags: { core: { sourceId: 'ballisticWeapon1' } }, system: { traits: ['ballistic'] } }
          : null));
        return {
          ...mockActor,
          items,
          getRollData: jest.fn(() => ({
            skills: { athletics: { modifier: '0', shift: 'd20' }, targeting: { modifier: '0', shift: 'd20' } },
          })),
          getFlag: jest.fn(() => undefined),
          setFlag: jest.fn(),
        };
      }

      let originalGetAutomaticCombatModifiers;
      beforeEach(() => {
        originalGetAutomaticCombatModifiers = dice._getAutomaticCombatModifiers;
      });
      afterEach(() => {
        dice._getAutomaticCombatModifiers = originalGetAutomaticCombatModifiers;
        game.combat = null;
      });

      test("offered on a ballistic-weapon roll that already carries a downshift", async () => {
        dice._getAutomaticCombatModifiers = jest.fn(() => hasShiftDownModifiers);
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        });
        dice._rollSkillHelper = jest.fn();
        const actor = makeGunslingerActor({ perkIds: [STRAIGHT_SHOOTER_TF_ID] });

        await dice.rollSkill(dataset, actor, ballisticWeaponEffect);

        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].straightShooterAvailable).toBe(true);
      });

      test("not offered without a downshift, without a ballistic weapon, without the Perk, or already used this turn", async () => {
        dice._rollSkillHelper = jest.fn();
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        });

        dice._getAutomaticCombatModifiers = jest.fn(() => noShiftDownModifiers);
        await dice.rollSkill(dataset, makeGunslingerActor({ perkIds: [STRAIGHT_SHOOTER_TF_ID] }), ballisticWeaponEffect);
        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].straightShooterAvailable).toBe(false);

        dice._getAutomaticCombatModifiers = jest.fn(() => hasShiftDownModifiers);
        await dice.rollSkill(
          dataset, makeGunslingerActor({ perkIds: [STRAIGHT_SHOOTER_TF_ID], hasWeapon: false }), ballisticWeaponEffect,
        );
        expect(rollDialog.getSkillRollOptions.mock.calls[1][0].straightShooterAvailable).toBe(false);

        await dice.rollSkill(dataset, makeGunslingerActor(), ballisticWeaponEffect);
        expect(rollDialog.getSkillRollOptions.mock.calls[2][0].straightShooterAvailable).toBe(false);

        game.combat = { id: 'c1', round: 1, turn: 0 };
        const usedActor = makeGunslingerActor({ perkIds: [STRAIGHT_SHOOTER_TF_ID] });
        usedActor.getFlag = jest.fn((scope, key) => (
          key == 'straightShooterUsedThisTurn' ? { combatId: 'c1', round: 1, turn: 0 } : undefined
        ));
        await dice.rollSkill(dataset, usedActor, ballisticWeaponEffect);
        expect(rollDialog.getSkillRollOptions.mock.calls[3][0].straightShooterAvailable).toBe(false);
      });

      test("applying it adds +1 shiftUp and marks the turn used", async () => {
        dice._getAutomaticCombatModifiers = jest.fn(() => hasShiftDownModifiers);
        const rollDialog = createMockRollDialog();
        const resolvedOptions = {
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
          applyStraightShooter: true,
        };
        rollDialog.getSkillRollOptions.mockReturnValue(resolvedOptions);
        dice._rollSkillHelper = jest.fn();
        game.combat = { id: 'c1', round: 1, turn: 0 };
        const actor = makeGunslingerActor({ perkIds: [STRAIGHT_SHOOTER_TF_ID] });

        await dice.rollSkill(dataset, actor, ballisticWeaponEffect);

        expect(resolvedOptions.shiftUp).toBe(1);
        expect(actor.setFlag).toHaveBeenCalledWith('essence20', 'straightShooterUsedThisTurn', expect.any(Object));
      });
    });

