  describe("Hobble (Decepticon Directive Raider, Acquisitions Expert Focus, 20th level, p.63)", () => {
    const HOBBLE_ID = "Compendium.essence20.decepticon_directive.Item.TG0CSb60LTv7jNyv";
    const rangedWeaponEffect = {
      type: 'weaponEffect',
      flags: {},
      system: { classification: { skill: 'targeting', style: 'projectile' }, damageType: 'ballistic', damageValue: 1 },
    };
    const meleeWeaponEffect = {
      type: 'weaponEffect',
      flags: {},
      system: { classification: { skill: 'might', style: 'melee' }, damageType: 'blunt', damageValue: 1 },
    };

    function makeActor({ hasPerk = true } = {}) {
      const items = hasPerk ? [{ type: 'perk', flags: { core: { sourceId: HOBBLE_ID } } }] : [];
      items.get = jest.fn(() => null);

      return {
        ...mockActor,
        items,
        getRollData: jest.fn(() => ({
          skills: {
            targeting: { modifier: '0', shift: 'd20' },
            might: { modifier: '0', shift: 'd20' },
          },
        })),
      };
    }

    // dataset.shift ('d20', the shared fixture's own default) wins over the actor's own skill
    // shift as rollSkill()'s initialShift - Hobble's own -2 downshift would otherwise drive an
    // untrained d20 die past this system's auto-fail floor before ever reaching
    // _rollSkillHelper, which isn't what these tests are checking, so start from the best shift
    // instead for the two tests that actually apply the downshift.
    const highShiftDataset = { ...dataset, shift: '3d6' };

    test("offered (hobbleAvailable) on a ranged attack with the Perk, not on melee or without it", async () => {
      const rollDialog = createMockRollDialog();
      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
      });
      dice._rollSkillHelper = jest.fn();

      await dice.rollSkill({ ...dataset, skill: 'targeting' }, makeActor(), rangedWeaponEffect);
      expect(rollDialog.getSkillRollOptions.mock.calls[0][0].hobbleAvailable).toBe(true);

      await dice.rollSkill({ ...dataset, skill: 'might' }, makeActor(), meleeWeaponEffect);
      expect(rollDialog.getSkillRollOptions.mock.calls[1][0].hobbleAvailable).toBe(false);

      await dice.rollSkill({ ...dataset, skill: 'targeting' }, makeActor({ hasPerk: false }), rangedWeaponEffect);
      expect(rollDialog.getSkillRollOptions.mock.calls[2][0].hobbleAvailable).toBe(false);
    });

    test("checking it adds a downshift 2 and flags the attempt on checkContext", async () => {
      const rollDialog = createMockRollDialog();
      const skillRollOptions = {
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        applyHobble: true,
      };
      rollDialog.getSkillRollOptions.mockReturnValue(skillRollOptions);
      dice._rollSkillHelper = jest.fn();

      await dice.rollSkill({ ...highShiftDataset, skill: 'targeting', dif: '10' }, makeActor(), rangedWeaponEffect);

      expect(skillRollOptions.shiftDown).toBe(2);
      const checkContext = dice._rollSkillHelper.mock.calls[0][4];
      expect(checkContext.hobbleAttempt).toBe(true);
    });

    test("leaves shiftDown alone and doesn't flag the attempt when unchecked", async () => {
      const rollDialog = createMockRollDialog();
      const skillRollOptions = {
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        applyHobble: false,
      };
      rollDialog.getSkillRollOptions.mockReturnValue(skillRollOptions);
      dice._rollSkillHelper = jest.fn();

      await dice.rollSkill({ ...dataset, skill: 'targeting', dif: '10' }, makeActor(), rangedWeaponEffect);

      expect(skillRollOptions.shiftDown).toBe(0);
      const checkContext = dice._rollSkillHelper.mock.calls[0][4];
      expect(checkContext.hobbleAttempt).toBe(false);
    });
  });

