  describe("Penetrating Aim (Decepticon Directive Raider, Siegemaster Focus, 1st level, p.63)", () => {
    const PENETRATING_AIM_ID = "Compendium.essence20.decepticon_directive.Item.Ill7m9IwlyXY0FMe";
    const rangedWeaponEffect = {
      type: 'weaponEffect',
      flags: {},
      system: { classification: { skill: 'targeting', style: 'projectile' }, damageType: 'ballistic', damageValue: 1, defenseType: 'toughness' },
    };
    const meleeWeaponEffect = {
      type: 'weaponEffect',
      flags: {},
      system: { classification: { skill: 'might', style: 'melee' }, damageType: 'blunt', damageValue: 1, defenseType: 'toughness' },
    };

    function makeActor({ hasPerk = true } = {}) {
      const items = hasPerk ? [{ type: 'perk', flags: { core: { sourceId: PENETRATING_AIM_ID } } }] : [];
      items.get = jest.fn(() => null);

      return {
        ...mockActor,
        items,
        getRollData: jest.fn(() => ({
          skills: {
            targeting: { modifier: '0', shift: 'd20' },
            might: { modifier: '0', shift: 'd20' },
          },
        })),
      };
    }

    test("offered (penetratingAimAvailable) on a ranged attack with the Perk, not on melee or without it", async () => {
      const rollDialog = createMockRollDialog();
      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
      });
      dice._rollSkillHelper = jest.fn();

      await dice.rollSkill({ ...dataset, skill: 'targeting' }, makeActor(), rangedWeaponEffect);
      expect(rollDialog.getSkillRollOptions.mock.calls[0][0].penetratingAimAvailable).toBe(true);

      await dice.rollSkill({ ...dataset, skill: 'might' }, makeActor(), meleeWeaponEffect);
      expect(rollDialog.getSkillRollOptions.mock.calls[1][0].penetratingAimAvailable).toBe(false);

      await dice.rollSkill({ ...dataset, skill: 'targeting' }, makeActor({ hasPerk: false }), rangedWeaponEffect);
      expect(rollDialog.getSkillRollOptions.mock.calls[2][0].penetratingAimAvailable).toBe(false);
    });

    test("checking it ignores 1 point of the target's armor Defense bonus", async () => {
      const rollDialog = createMockRollDialog();
      rollDialog.getSkillRollOptions.mockReturnValue({
        canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        applyPenetratingAim: true, defenseType: 'toughness',
      });
      const targetActor = {
        system: { isMorphed: false, defenses: { toughness: { total: 15, armor: 4 } } },
        name: 'Target',
        uuid: 'Actor.target1',
      };
      const targetsList = [{ actor: targetActor }];
      targetsList.first = () => undefined;
      global.game.user.targets = targetsList;
      dice._rollSkillHelper = jest.fn();

      try {
        await dice.rollSkill({ ...dataset, skill: 'targeting' }, makeActor(), rangedWeaponEffect);

        const checkContext = dice._rollSkillHelper.mock.calls[0][4];
        expect(checkContext.entries[0].difficulty).toBe(14); // 15 total - 1 (of 4) armor points
      } finally {
        global.game.user.targets = { first: jest.fn(() => undefined) };
      }
    });

    test("doesn't reduce difficulty without the Perk, unchecked, or against a non-Toughness Defense", async () => {
      const rollDialog = createMockRollDialog();
      const targetActor = {
        system: { isMorphed: false, defenses: { toughness: { total: 15, armor: 4 }, evasion: { total: 12, armor: 0 } } },
        name: 'Target',
        uuid: 'Actor.target1',
      };
      const targetsList = [{ actor: targetActor }];
      targetsList.first = () => undefined;
      global.game.user.targets = targetsList;
      dice._rollSkillHelper = jest.fn();

      try {
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
          applyPenetratingAim: true, defenseType: 'toughness',
        });
        await dice.rollSkill({ ...dataset, skill: 'targeting' }, makeActor({ hasPerk: false }), rangedWeaponEffect);
        expect(dice._rollSkillHelper.mock.calls[0][4].entries[0].difficulty).toBe(15);

        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
          applyPenetratingAim: false, defenseType: 'toughness',
        });
        await dice.rollSkill({ ...dataset, skill: 'targeting' }, makeActor(), rangedWeaponEffect);
        expect(dice._rollSkillHelper.mock.calls[1][4].entries[0].difficulty).toBe(15);

        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
          applyPenetratingAim: true, defenseType: 'evasion',
        });
        await dice.rollSkill({ ...dataset, skill: 'targeting' }, makeActor(), rangedWeaponEffect);
        expect(dice._rollSkillHelper.mock.calls[2][4].entries[0].difficulty).toBe(12);
      } finally {
        global.game.user.targets = { first: jest.fn(() => undefined) };
      }
    });
  });

