      await dice.rollSkill(meleeDataset, actor, makeMeleeWeaponEffect({ numHands: 2 }));

      expect(rollDialog.getSkillRollOptions.mock.calls[0][0]).toMatchObject({ twoHandedAssaultAvailable: true });
