    describe("Hesher (Factions in Action Vol. 2, General Perk, p.64)", () => {
      const HESHER_ID = "Compendium.essence20.intercontinental_adventures.Item.4PCn3kSSYmPtQOUM";

      function makeActor({ choice = null, performanceShift = 'd10' } = {}) {
        const items = choice
          ? [{ type: 'perk', flags: { core: { sourceId: HESHER_ID } }, system: { choice } }]
          : [];
        items.get = jest.fn(() => null);

        return {
          ...mockActor,
          items,
          getRollData: jest.fn(() => ({
            skills: {
              intimidation: { modifier: '0', shift: 'd20' },
              performance: { modifier: '0', shift: performanceShift },
            },
          })),
        };
      }

      test("hesherAvailable is true only when the current roll matches the chosen skill", async () => {
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        });
        dice._rollSkillHelper = jest.fn();

        await dice.rollSkill({ ...dataset, skill: 'intimidation' }, makeActor({ choice: 'intimidation' }), null);
        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].hesherAvailable).toBe(true);

        await dice.rollSkill({ ...dataset, skill: 'intimidation' }, makeActor({ choice: 'persuasion' }), null);
        expect(rollDialog.getSkillRollOptions.mock.calls[1][0].hesherAvailable).toBe(false);
      });

      test("substitutes the Performance die as a shiftUp when checked", async () => {
        const rollDialog = createMockRollDialog();
        const returnedOptions = {
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1, applyHesher: true,
        };
        rollDialog.getSkillRollOptions.mockReturnValue(returnedOptions);
        dice._rollSkillHelper = jest.fn();
        const actor = makeActor({ choice: 'intimidation', performanceShift: 'd10' });
        actor.getRollData = jest.fn(() => ({
          skills: { intimidation: { modifier: '0', shift: 'd6' }, performance: { modifier: '0', shift: 'd10' } },
        }));

        await dice.rollSkill({ ...dataset, skill: 'intimidation', essence: 'social', shift: 'd6' }, actor, null);

        expect(returnedOptions.shiftUp).toBe(2);
        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].hesherAvailable).toBe(true);
      });

      test("doesn't change the shift when unchecked, even if available", async () => {
        const rollDialog = createMockRollDialog();
        const returnedOptions = {
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1, applyHesher: false,
        };
        rollDialog.getSkillRollOptions.mockReturnValue(returnedOptions);
        dice._rollSkillHelper = jest.fn();
        const actor = makeActor({ choice: 'intimidation', performanceShift: 'd10' });
        actor.getRollData = jest.fn(() => ({
          skills: { intimidation: { modifier: '0', shift: 'd6' }, performance: { modifier: '0', shift: 'd10' } },
        }));

        await dice.rollSkill({ ...dataset, skill: 'intimidation', essence: 'social', shift: 'd6' }, actor, null);

        expect(returnedOptions.shiftUp).toBe(0);
      });
    });

