    describe("Exemplary (GI Joe CRB, Focus: Frontline Leader, 10th level, p.87)", () => {
      const EXEMPLARY_ID = "Compendium.essence20.gi_joe_crb.Item.jpu756uKYfydTu16";

      function makeRollingActor() {
        const actorToken = { document: { disposition: 1 }, center: { x: 0, y: 0 } };
        return { ...makeActor(), getActiveTokens: jest.fn(() => [actorToken]) };
      }

      function makeExemplaryAllyToken({ hasPerk = true, lastSkill = 'might', disposition = 1 } = {}) {
        return {
          actor: {
            items: hasPerk ? [{ type: 'perk', flags: { core: { sourceId: EXEMPLARY_ID } } }] : [],
            getFlag: jest.fn(() => lastSkill),
          },
          document: { disposition },
          center: { x: 5, y: 0 },
        };
      }

      afterEach(() => {
        canvas.tokens.placeables = [];
      });

      test("grants Edge when a nearby ally holds the Perk and last rolled the same skill", async () => {
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        });
        dice._rollSkillHelper = jest.fn();
        const actor = makeRollingActor();
        canvas.tokens.placeables = [makeExemplaryAllyToken({ lastSkill: 'might' })];

        await dice.rollSkill({ ...dataset, skill: 'might', essence: 'strength' }, actor, null);

        expect(rollDialog.getSkillRollOptions.mock.calls[0][1].edge).toBe(true);
      });

      test("doesn't apply when the ally's last skill doesn't match, or without the Perk nearby", async () => {
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        });
        dice._rollSkillHelper = jest.fn();

        canvas.tokens.placeables = [makeExemplaryAllyToken({ lastSkill: 'persuasion' })];
        await dice.rollSkill({ ...dataset, skill: 'might', essence: 'strength' }, makeRollingActor(), null);
        expect(rollDialog.getSkillRollOptions.mock.calls[0][1].edge).toBe(false);

        canvas.tokens.placeables = [makeExemplaryAllyToken({ hasPerk: false })];
        await dice.rollSkill({ ...dataset, skill: 'might', essence: 'strength' }, makeRollingActor(), null);
        expect(rollDialog.getSkillRollOptions.mock.calls[1][1].edge).toBe(false);
      });
    });

