    describe("Seeing the Matrix (GI Joe CRB, Focus: Tinkerer, 6th level, p.105)", () => {
      const SEEING_THE_MATRIX_ID = "Compendium.essence20.gi_joe_crb.Item.M8D4FRcfaGm5i2jH";

      function makeTinkererActor({ hasPerk = true, usedThisEncounter = false } = {}) {
        const items = hasPerk ? [{ type: 'perk', flags: { core: { sourceId: SEEING_THE_MATRIX_ID } } }] : [];
        items.get = jest.fn(() => null);
        return {
          ...mockActor,
          items,
          getFlag: jest.fn((scope, key) => (
            key == 'seeingTheMatrixUsedThisEncounter' && usedThisEncounter ? { epoch: 1, window: 'encounter', count: 1 } : undefined
          )),
          setFlag: jest.fn(),
          getRollData: jest.fn(() => ({
            skills: { might: { modifier: '0', shift: 'd6' }, technology: { modifier: '0', shift: 'd10' } },
          })),
        };
      }

      afterEach(() => {
        game.combat = null;
      });

      test("substitutes the actor's own better Technology die as a shiftUp when checked, and marks the encounter used", async () => {
        game.combat = { id: 'c1' };
        const rollDialog = createMockRollDialog();
        const returnedOptions = {
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1, applySeeingTheMatrix: true,
        };
        rollDialog.getSkillRollOptions.mockReturnValue(returnedOptions);
        dice._rollSkillHelper = jest.fn();
        const actor = makeTinkererActor();

        await dice.rollSkill({ ...dataset, skill: 'might', essence: 'strength', shift: 'd6' }, actor, null);

        // d10 is 2 positions better than d6 in E20.skillShiftList, so the delta becomes a +2 shiftUp.
        expect(returnedOptions.shiftUp).toBe(2);
        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].seeingTheMatrixAvailable).toBe(true);
        expect(actor.setFlag).toHaveBeenCalledWith(
          'essence20', 'seeingTheMatrixUsedThisEncounter', expect.objectContaining({ epoch: 1, window: 'encounter', count: 1 }),
        );
      });

      test("doesn't change the shift when unchecked, even if available", async () => {
        const rollDialog = createMockRollDialog();
        const returnedOptions = {
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1, applySeeingTheMatrix: false,
        };
        rollDialog.getSkillRollOptions.mockReturnValue(returnedOptions);
        dice._rollSkillHelper = jest.fn();

        await dice.rollSkill({ ...dataset, skill: 'might', essence: 'strength', shift: 'd6' }, makeTinkererActor(), null);

        expect(returnedOptions.shiftUp).toBe(0);
      });

      test("seeingTheMatrixAvailable is false on a Technology roll, without the Perk, or once already used this encounter", async () => {
        const rollDialog = createMockRollDialog();
        rollDialog.getSkillRollOptions.mockReturnValue({
          canCritD2: false, edge: false, snag: false, shiftUp: 0, shiftDown: 0, timesToRoll: 1,
        });
        dice._rollSkillHelper = jest.fn();

        await dice.rollSkill({ ...dataset, skill: 'technology', essence: 'smarts' }, makeTinkererActor(), null);
        expect(rollDialog.getSkillRollOptions.mock.calls[0][0].seeingTheMatrixAvailable).toBe(false);

        await dice.rollSkill(
          { ...dataset, skill: 'might', essence: 'strength', shift: 'd6' }, makeTinkererActor({ hasPerk: false }), null,
        );
        expect(rollDialog.getSkillRollOptions.mock.calls[1][0].seeingTheMatrixAvailable).toBe(false);

        game.combat = { id: 'c1' };
        await dice.rollSkill(
          { ...dataset, skill: 'might', essence: 'strength', shift: 'd6' },
          makeTinkererActor({ usedThisEncounter: true }), null,
        );
        expect(rollDialog.getSkillRollOptions.mock.calls[2][0].seeingTheMatrixAvailable).toBe(false);
      });
    });

