    const actor = makeActor('common');

    expect(dice._getAutomaticCombatModifiers(actor, meleeWeaponEffect))
      .toEqual({ ...defaultModifiers, snag: true, sources: [
        {
          "edge": false,
          "id": "targetInvisible",
          "label": "E20.StatusInvisible",
          "shiftDown": 0,
          "shiftUp": 0,
          "snag": true,
        },
      ] });
