  describe("Accurate / Inaccurate (standard weapon traits, all game lines)", () => {
    // _getParentWeapon resolves the parent via this flag, so an attack fixture needs one to have
    // any parent weapon at all.
    const attack = { ...meleeWeaponEffect, flags: { essence20: { parentId: 'weapon1' } } };

    function source(id, label, shift) {
      return { edge: false, id, label, shiftDown: 0, shiftUp: 0, snag: false, ...shift };
    }

    function makeWielder(traits) {
      return makeActor('common', [], { weapon: { system: { traits } } });
    }

    test("an Accurate weapon grants ↑1", () => {
      expect(dice._getAutomaticCombatModifiers(makeWielder(['accurate']), attack))
        .toEqual({ ...defaultModifiers, shiftUp: 1, sources: [
          source('accurateWeapon', 'E20.WeaponTraitAccurate', { shiftUp: 1 }),
        ] });
    });

    test("an Inaccurate weapon imposes ↓1", () => {
      expect(dice._getAutomaticCombatModifiers(makeWielder(['inaccurate']), attack))
        .toEqual({ ...defaultModifiers, shiftDown: 1, sources: [
          source('inaccurateWeapon', 'E20.WeaponTraitInaccurate', { shiftDown: 1 }),
        ] });
    });

    test("a weapon carrying both nets to zero, listing each as its own source", () => {
      // Horseman's Lance (A Jump Through Time) genuinely ships with both traits.
      expect(dice._getAutomaticCombatModifiers(makeWielder(['accurate', 'inaccurate']), attack))
        .toEqual({ ...defaultModifiers, shiftUp: 1, shiftDown: 1, sources: [
          source('accurateWeapon', 'E20.WeaponTraitAccurate', { shiftUp: 1 }),
          source('inaccurateWeapon', 'E20.WeaponTraitInaccurate', { shiftDown: 1 }),
        ] });
    });

    test("a weapon with neither trait is unaffected", () => {
      expect(dice._getAutomaticCombatModifiers(makeWielder(['ballistic']), attack))
        .toEqual(defaultModifiers);
    });

    test("doesn't apply to an attack with no parent weapon", () => {
      expect(dice._getAutomaticCombatModifiers(makeWielder(['accurate']), meleeWeaponEffect))
        .toEqual(defaultModifiers);
    });

    test("doesn't apply to a non-attack roll", () => {
      expect(dice._getAutomaticCombatModifiers(makeWielder(['accurate']), null))
        .toEqual(defaultModifiers);
    });

    function makeWielderWithMagnitude(traits, magnitudes) {
      return makeActor('common', [], { weapon: { system: { traits, ...magnitudes } } });
    }

    test("Inaccurate honours a higher printed magnitude (Cannonade/Catapult's ↓2)", () => {
      const wielder = makeWielderWithMagnitude(['inaccurate'], { inaccurateMagnitude: 2 });
      expect(dice._getAutomaticCombatModifiers(wielder, attack))
        .toEqual({ ...defaultModifiers, shiftDown: 2, sources: [
          source('inaccurateWeapon', 'E20.WeaponTraitInaccurate', { shiftDown: 2 }),
        ] });
    });

    test("Inaccurate honours an even higher magnitude (Transdagger Star Formation's ↓3)", () => {
      const wielder = makeWielderWithMagnitude(['inaccurate'], { inaccurateMagnitude: 3 });
      expect(dice._getAutomaticCombatModifiers(wielder, attack))
        .toEqual({ ...defaultModifiers, shiftDown: 3, sources: [
          source('inaccurateWeapon', 'E20.WeaponTraitInaccurate', { shiftDown: 3 }),
        ] });
    });

    test("Accurate likewise honours a non-default magnitude", () => {
      const wielder = makeWielderWithMagnitude(['accurate'], { accurateMagnitude: 2 });
      expect(dice._getAutomaticCombatModifiers(wielder, attack))
        .toEqual({ ...defaultModifiers, shiftUp: 2, sources: [
          source('accurateWeapon', 'E20.WeaponTraitAccurate', { shiftUp: 2 }),
        ] });
    });

    describe("Pyromania (Cobra Codex, Ranger Guerilla Focus, 3rd level, p.58)", () => {
      const PYROMANIA_ID = "Compendium.essence20.cobra_codex.Item.gvpgK9oegrloYHcO";

      function makeWielderWithLevel(traits, level) {
        return makeActor('common', [], { weapon: { system: { traits } }, perkIds: [PYROMANIA_ID], level });
      }

      test("↑1 with a Fire weapon below 10th level", () => {
        expect(dice._getAutomaticCombatModifiers(makeWielderWithLevel(['fire'], 3), attack))
          .toEqual({ ...defaultModifiers, shiftUp: 1, sources: [
            source('pyromania', 'Pyromania', { shiftUp: 1 }),
          ] });
      });

      test("↓1 with a non-Fire weapon below 10th level", () => {
        expect(dice._getAutomaticCombatModifiers(makeWielderWithLevel(['ballistic'], 3), attack))
          .toEqual({ ...defaultModifiers, shiftDown: 1, sources: [
            source('pyromania', 'Pyromania', { shiftDown: 1 }),
          ] });
      });

      test("↑2/↓2 at 10th level", () => {
        expect(dice._getAutomaticCombatModifiers(makeWielderWithLevel(['fire'], 10), attack).shiftUp).toBe(2);
        expect(dice._getAutomaticCombatModifiers(makeWielderWithLevel([], 10), attack).shiftDown).toBe(2);
      });

      test("↑3/↓3 at 20th level", () => {
        expect(dice._getAutomaticCombatModifiers(makeWielderWithLevel(['fire'], 20), attack).shiftUp).toBe(3);
        expect(dice._getAutomaticCombatModifiers(makeWielderWithLevel([], 20), attack).shiftDown).toBe(3);
      });

      test("doesn't apply without the Perk", () => {
        const wielder = makeActor('common', [], { weapon: { system: { traits: ['fire'] } }, level: 3 });
        expect(dice._getAutomaticCombatModifiers(wielder, attack)).toEqual(defaultModifiers);
      });

      test("doesn't apply to a non-attack roll", () => {
        expect(dice._getAutomaticCombatModifiers(makeWielderWithLevel(['fire'], 3), null)).toEqual(defaultModifiers);
      });
    });

    test("falls back to 1 when the magnitude field is unset (existing compendium weapons)", () => {
      const wielder = makeWielderWithMagnitude(['inaccurate'], {});
      expect(dice._getAutomaticCombatModifiers(wielder, attack))
        .toEqual({ ...defaultModifiers, shiftDown: 1, sources: [
          source('inaccurateWeapon', 'E20.WeaponTraitInaccurate', { shiftDown: 1 }),
        ] });
    });
  });

  describe("Shield Modulation (Vanguard base, 13th level, p.109)", () => {
    const SHIELD_MODULATION_ID = `${GI_JOE_CRB}16ul4Ev6b9gO5CIN`;
    const PERSONAL_SHIELD_ROLE_POINTS_ID = `${GI_JOE_CRB}84JYgd6kZgY41wge`;
    const fireWeaponEffect = { ...meleeWeaponEffect, system: { ...meleeWeaponEffect.system, damageType: 'fire' } };
    const poisonWeaponEffect = { ...meleeWeaponEffect, system: { ...meleeWeaponEffect.system, damageType: 'poison' } };

    function makeShieldedTarget({ perkIds = [], shieldActive = true, modulatedType = null } = {}) {
      const target = makeActor('common', [], { perkIds });
      target._getBaseRolePoints = jest.fn(() => ({
        flags: { core: { sourceId: PERSONAL_SHIELD_ROLE_POINTS_ID } },
        system: {
          isActive: shieldActive, isActivatable: true,
          bonus: { type: 'defenseBonus', defenseBonus: { toughness: true, evasion: true } },
        },
      }));
      target.getFlag = jest.fn((scope, key) => {
        if (scope != 'essence20') return undefined;
        if (key == 'shieldModulationDamageType') return modulatedType;
        return undefined;
      });

      return target;
    }

    test("Snags an attack matching the chosen damage type", () => {
      game.user.targets.first.mockReturnValue({
        actor: makeShieldedTarget({ perkIds: [SHIELD_MODULATION_ID], modulatedType: 'fire' }),
      });
      const actor = makeActor('common');

      expect(dice._getAutomaticCombatModifiers(actor, fireWeaponEffect))
        .toEqual({ ...defaultModifiers, snag: true, sources: [
          {
            "edge": false,
            "id": "shieldModulation",
            "label": "Shield Modulation",
            "shiftDown": 0,
            "shiftUp": 0,
            "snag": true,
          },
        ] });
    });

    test("doesn't apply to a different damage type than the one chosen", () => {
      game.user.targets.first.mockReturnValue({
        actor: makeShieldedTarget({ perkIds: [SHIELD_MODULATION_ID], modulatedType: 'poison' }),
      });
      const actor = makeActor('common');

      expect(dice._getAutomaticCombatModifiers(actor, fireWeaponEffect)).toEqual(defaultModifiers);
    });

    test("doesn't apply without the shield active", () => {
      game.user.targets.first.mockReturnValue({
        actor: makeShieldedTarget({ perkIds: [SHIELD_MODULATION_ID], modulatedType: 'fire', shieldActive: false }),
      });
      const actor = makeActor('common');

      expect(dice._getAutomaticCombatModifiers(actor, fireWeaponEffect)).toEqual(defaultModifiers);
    });

    test("doesn't apply without the Perk, even with a stored damage type", () => {
      game.user.targets.first.mockReturnValue({ actor: makeShieldedTarget({ modulatedType: 'fire' }) });
      const actor = makeActor('common');

      expect(dice._getAutomaticCombatModifiers(actor, fireWeaponEffect)).toEqual(defaultModifiers);
    });

    test("doesn't apply without a damage type ever chosen", () => {
      game.user.targets.first.mockReturnValue({ actor: makeShieldedTarget({ perkIds: [SHIELD_MODULATION_ID] }) });
      const actor = makeActor('common');

      expect(dice._getAutomaticCombatModifiers(actor, poisonWeaponEffect)).toEqual(defaultModifiers);
    });
  });

  describe("Enemy Number One (Tank Focus, 3rd level)", () => {
    const ENEMY_NUMBER_ONE_ID = "Compendium.essence20.gi_joe_crb.Item.zvzta73A3ROyxv0J";

    function makeToken(actor, disposition) {
      return { actor, center: { x: 0, y: 0 }, document: { disposition } };
    }

    function makeTank(id) {
      return {
        id,
        system: { size: 'common' },
        statuses: new Set(),
        items: [{ type: 'perk', flags: { core: { sourceId: ENEMY_NUMBER_ONE_ID } } }],
      };
    }

    // attackedFlag simulates actor.getFlag('essence20', 'attackedEnemyNumberOneThisTurn')'s
    // stored value - undefined unless a test explicitly provides one. Keyed on `key` so it
    // doesn't also answer the unrelated getFlag('essence20', 'debilitated') check this same
    // function makes for every roll.
    function makeAttacker(token, attackedFlag = undefined) {
      return {
        system: { size: 'common' },
        statuses: new Set(),
        items: [],
        getActiveTokens: jest.fn(() => [token]),
        getFlag: jest.fn((scope, key) => (
          scope == 'essence20' && key == 'attackedEnemyNumberOneThisTurn' ? attackedFlag : undefined
        )),
        unsetFlag: jest.fn(),
      };
    }

    beforeEach(() => {
      canvas.tokens.placeables = [];
      canvas.grid.measurePath.mockReturnValue({ distance: 10 });
      game.combat = { id: 'combat1', round: 1, turn: 0 };
    });

    afterEach(() => {
      game.combat = null;
    });

    test("suffers a Snag attacking someone else near an enemy Tank", () => {
      const attackerToken = makeToken(null, 1);
      const tank = makeTank('tank1');
      canvas.tokens.placeables = [attackerToken, makeToken(tank, -1)];
      game.user.targets.first.mockReturnValue({ actor: makeActor('common') });

      expect(dice._getAutomaticCombatModifiers(makeAttacker(attackerToken), meleeWeaponEffect))
        .toEqual({ ...defaultModifiers, snag: true, sources: [
          {
            "edge": false,
            "id": "enemyNumberOne",
            "label": "Enemy Number One",
            "shiftDown": 0,
            "shiftUp": 0,
            "snag": true,
          },
        ] });
    });

    test("doesn't Snag an attack against the Tank itself, and flags that Tank for later", () => {
      const attackerToken = makeToken(null, 1);
      const tank = makeTank('tank1');
      canvas.tokens.placeables = [attackerToken, makeToken(tank, -1)];
      game.user.targets.first.mockReturnValue({ actor: tank });

      expect(dice._getAutomaticCombatModifiers(makeAttacker(attackerToken), meleeWeaponEffect))
        .toEqual({ ...defaultModifiers, enemyNumberOneTankId: 'tank1' });
    });

    test("doesn't apply once the attacker already attacked that Tank this turn", () => {
      const attackerToken = makeToken(null, 1);
      const tank = makeTank('tank1');
      canvas.tokens.placeables = [attackerToken, makeToken(tank, -1)];
      game.user.targets.first.mockReturnValue({ actor: makeActor('common') });
      const attacker = makeAttacker(attackerToken, { combatId: 'combat1', round: 1, turn: 0, tankId: 'tank1' });

      expect(dice._getAutomaticCombatModifiers(attacker, meleeWeaponEffect)).toEqual(defaultModifiers);
    });

    test("applies again once it's a new turn, despite a stale flag from an earlier turn", () => {
      const attackerToken = makeToken(null, 1);
      const tank = makeTank('tank1');
      canvas.tokens.placeables = [attackerToken, makeToken(tank, -1)];
      game.user.targets.first.mockReturnValue({ actor: makeActor('common') });
      const attacker = makeAttacker(attackerToken, { combatId: 'combat1', round: 1, turn: 0, tankId: 'tank1' });
      game.combat = { id: 'combat1', round: 1, turn: 2 };

      expect(dice._getAutomaticCombatModifiers(attacker, meleeWeaponEffect))
        .toEqual({ ...defaultModifiers, snag: true, sources: [
          {
            "edge": false,
            "id": "enemyNumberOne",
            "label": "Enemy Number One",
            "shiftDown": 0,
            "shiftUp": 0,
            "snag": true,
          },
        ] });
    });

    test("doesn't apply outside of combat", () => {
      const attackerToken = makeToken(null, 1);
      const tank = makeTank('tank1');
      canvas.tokens.placeables = [attackerToken, makeToken(tank, -1)];
      game.user.targets.first.mockReturnValue({ actor: makeActor('common') });
      game.combat = null;

      expect(dice._getAutomaticCombatModifiers(makeAttacker(attackerToken), meleeWeaponEffect))
        .toEqual(defaultModifiers);
    });

    test("doesn't apply beyond 30 feet", () => {
      const attackerToken = makeToken(null, 1);
      const tank = makeTank('tank1');
      canvas.tokens.placeables = [attackerToken, makeToken(tank, -1)];
      canvas.grid.measurePath.mockReturnValue({ distance: 35 });
      game.user.targets.first.mockReturnValue({ actor: makeActor('common') });

      expect(dice._getAutomaticCombatModifiers(makeAttacker(attackerToken), meleeWeaponEffect))
        .toEqual(defaultModifiers);
    });

    test("doesn't apply to an allied Tank (same disposition as the attacker)", () => {
      const attackerToken = makeToken(null, 1);
      const tank = makeTank('tank1');
      canvas.tokens.placeables = [attackerToken, makeToken(tank, 1)];
      game.user.targets.first.mockReturnValue({ actor: makeActor('common') });

      expect(dice._getAutomaticCombatModifiers(makeAttacker(attackerToken), meleeWeaponEffect))
        .toEqual(defaultModifiers);
    });

    test("doesn't apply without any nearby Tank", () => {
      const attackerToken = makeToken(null, 1);
      canvas.tokens.placeables = [attackerToken];
      game.user.targets.first.mockReturnValue({ actor: makeActor('common') });

      expect(dice._getAutomaticCombatModifiers(makeAttacker(attackerToken), meleeWeaponEffect))
        .toEqual(defaultModifiers);
    });
  });

