  describe("Large And In Charge (Transformers CRB, Origin Perk, Monolith Chassis, p.51)", () => {
    const LARGE_AND_IN_CHARGE_ID = "Compendium.essence20.tf_crb.Item.Rj9N6i7Jmkl54ujX";

    function makeMonolithActor(size, choice = 'persuasion') {
      const actor = makeActor(size);
      actor.items.push({ type: 'perk', flags: { core: { sourceId: LARGE_AND_IN_CHARGE_ID } }, system: { choice } });
      return actor;
    }

    test("upshifts the chosen skill by a flat 1 against a smaller target", () => {
      const target = makeActor('small');
      game.user.targets.first.mockReturnValue({ actor: target });
      const actor = makeMonolithActor('common');

      const result = dice._getAutomaticCombatModifiers(actor, null, null, 'persuasion');
      expect(result.shiftUp).toBe(1);
      expect(result.sources.some(s => s.id == 'largeAndInCharge')).toBe(true);
    });

    test("doesn't scale with the size difference, unlike Big And Scary", () => {
      const target = makeActor('small');
      game.user.targets.first.mockReturnValue({ actor: target });
      const actor = makeMonolithActor('long'); // long(3) vs small(0), a bigger gap than the test above

      expect(dice._getAutomaticCombatModifiers(actor, null, null, 'persuasion').shiftUp).toBe(1);
    });

    test("doesn't apply against an equal or larger target, on a different skill, or without a choice made", () => {
      const actor = makeMonolithActor('common');

      game.user.targets.first.mockReturnValue({ actor: makeActor('common') });
      expect(dice._getAutomaticCombatModifiers(actor, null, null, 'persuasion')).toEqual(defaultModifiers);

      game.user.targets.first.mockReturnValue({ actor: makeActor('small') });
      expect(dice._getAutomaticCombatModifiers(actor, null, null, 'deception')).toEqual(defaultModifiers);

      const noChoiceActor = makeActor('common');
      noChoiceActor.items.push({ type: 'perk', flags: { core: { sourceId: LARGE_AND_IN_CHARGE_ID } }, system: {} });
      expect(dice._getAutomaticCombatModifiers(noChoiceActor, null, null, 'persuasion')).toEqual(defaultModifiers);
    });
  });

