  describe("Bumper Crop (WTNV Citizen's Guide, Farmer Role, Tiller Focus, p.37) - Snag application", () => {
    function makeEnemyToken(disposition, id) {
      return { document: { disposition }, center: {}, actor: { id, setFlag: jest.fn() } };
    }

    beforeEach(() => {
      canvas.tokens.placeables = [];
      canvas.grid.measurePath.mockReturnValue({ distance: 10 });
    });

    test("Snags 1 + floor(margin/5) nearby enemies on a success", async () => {
      global.Roll = FakeRoll;
      FakeRoll.nextTotal = 21; // beats DIF 10 by 11 -> 1 + floor(11/5) = 3 targets
      const actorToken = { document: { disposition: 1 }, center: {} };
      const enemy1 = makeEnemyToken(-1, 'e1');
      const enemy2 = makeEnemyToken(-1, 'e2');
      const enemy3 = makeEnemyToken(-1, 'e3');
      canvas.tokens.placeables = [actorToken, enemy1, enemy2, enemy3];
      const actor = { ...makeBankedActor(false), getActiveTokens: jest.fn(() => [actorToken]) };
      const checkContext = {
        entries: [{ name: 'Target', targetUuid: null, difficulty: 10, showDifficulty: true }],
        damageValue: null, damageType: null, effectName: null, alternateEffects: [],
        isBumperCropAttempt: true,
      };

      await freshDice._rollSkillHelper('d20 + 0', actor, 'flavor', false, checkContext, {});

      expect(enemy1.actor.setFlag).toHaveBeenCalledWith('essence20', 'pendingBumperCropSnag', expect.objectContaining({ snag: true }));
      expect(enemy2.actor.setFlag).toHaveBeenCalled();
      expect(enemy3.actor.setFlag).toHaveBeenCalled();
    });

    test("doesn't Snag anyone on a failed roll, or without the attempt flagged", async () => {
      global.Roll = FakeRoll;
      const actorToken = { document: { disposition: 1 }, center: {} };
      const enemy = makeEnemyToken(-1, 'e1');
      canvas.tokens.placeables = [actorToken, enemy];
      const actor = { ...makeBankedActor(false), getActiveTokens: jest.fn(() => [actorToken]) };

      FakeRoll.nextTotal = 5; // below DIF 10 - a miss
      const checkContext = {
        entries: [{ name: 'Target', targetUuid: null, difficulty: 10, showDifficulty: true }],
        damageValue: null, damageType: null, effectName: null, alternateEffects: [],
        isBumperCropAttempt: true,
      };
      await freshDice._rollSkillHelper('d20 + 0', actor, 'flavor', false, checkContext, {});
      expect(enemy.actor.setFlag).not.toHaveBeenCalled();

      FakeRoll.nextTotal = 21;
      await freshDice._rollSkillHelper(
        'd20 + 0', actor, 'flavor', false, { ...checkContext, isBumperCropAttempt: false }, {},
      );
      expect(enemy.actor.setFlag).not.toHaveBeenCalled();
    });
  });

