  describe("Metallikato (Decepticon Directive, General Perk, p.66) - trip on Critical Success", () => {
    const METALLIKATO_ID = "Compendium.essence20.decepticon_directive.Item.ouLZnb7j0kAfCrLx";

    function makeMetallikatoActor({ hasPerk = true, isTransformed = false } = {}) {
      const items = hasPerk ? [{ type: 'perk', flags: { core: { sourceId: METALLIKATO_ID } } }] : [];
      items.get = jest.fn(() => null);
      return {
        ...mockActor,
        items,
        system: { ...mockActor.system, isTransformed },
        getRollData: jest.fn(() => ({})),
        getFlag: jest.fn(() => undefined),
      };
    }

    // A local Roll standing in for FakeRoll above, showing a natural max face on a non-d20 die -
    // isCrit (combat.mjs#_isCritIsFumble) needs a real crit-shaped dice pool, unlike FakeRoll's
    // own shared d8-showing-1 fixture (built for reroll tests, not Crit ones).
    class CritRoll {
      constructor() {
        this.dice = [{ faces: 20, values: [15] }, { faces: 8, values: [8] }];
        this._total = 30;
      }
      async evaluate() {}
      get total() {
        return this._total; 
      }
      _evaluateTotal() {
        return this._total; 
      }
      async render() {
        return '<div></div>'; 
      }
    }
    class NonCritRoll {
      constructor() {
        this.dice = [{ faces: 20, values: [15] }, { faces: 8, values: [3] }];
        this._total = 18;
      }
      async evaluate() {}
      get total() {
        return this._total; 
      }
      _evaluateTotal() {
        return this._total; 
      }
      async render() {
        return '<div></div>'; 
      }
    }

    const meleeCheckContext = {
      entries: [{ name: 'Target', targetUuid: 'Actor.target1', difficulty: 10, showDifficulty: true }],
      damageValue: 1, damageType: 'blunt', effectName: 'Test Weapon Effect', alternateEffects: [],
      isMelee: true,
    };

    test("knocks a successfully-hit target Prone on a Critical Success, in Bot Mode with the Perk", async () => {
      const targetActor = { toggleStatusEffect: jest.fn() };
      fromUuid.mockResolvedValue(targetActor);
      global.Roll = CritRoll;

      await freshDice._rollSkillHelper('d20 + 0', makeMetallikatoActor(), 'flavor', false, meleeCheckContext, {});

      expect(targetActor.toggleStatusEffect).toHaveBeenCalledWith('prone', { active: true });
    });

    test("doesn't apply on a non-Critical hit", async () => {
      const targetActor = { toggleStatusEffect: jest.fn() };
      fromUuid.mockResolvedValue(targetActor);
      global.Roll = NonCritRoll;

      await freshDice._rollSkillHelper('d20 + 0', makeMetallikatoActor(), 'flavor', false, meleeCheckContext, {});

      expect(targetActor.toggleStatusEffect).not.toHaveBeenCalled();
    });

    test("doesn't apply without the Perk, in Alt Mode, or on a non-melee roll", async () => {
      const targetActor = { toggleStatusEffect: jest.fn() };
      fromUuid.mockResolvedValue(targetActor);
      global.Roll = CritRoll;

      await freshDice._rollSkillHelper(
        'd20 + 0', makeMetallikatoActor({ hasPerk: false }), 'flavor', false, meleeCheckContext, {},
      );
      expect(targetActor.toggleStatusEffect).not.toHaveBeenCalled();

      await freshDice._rollSkillHelper(
        'd20 + 0', makeMetallikatoActor({ isTransformed: true }), 'flavor', false, meleeCheckContext, {},
      );
      expect(targetActor.toggleStatusEffect).not.toHaveBeenCalled();

      await freshDice._rollSkillHelper(
        'd20 + 0', makeMetallikatoActor(), 'flavor', false, { ...meleeCheckContext, isMelee: false }, {},
      );
      expect(targetActor.toggleStatusEffect).not.toHaveBeenCalled();
    });
  });

